import { acquireImageSlot } from '@/utils/imageQueue';
export default {
  name: 'FileCard',
  props: {
    item: {
      type: Object,
      required: true
    },
    selected: {
      type: Boolean,
      default: false
    },
    fileLink: {
      type: String,
      required: true
    },
    previewSrcList: {
      type: Array,
      default: () => []
    },
    disableTooltip: {
      type: Boolean,
      default: false
    }
  },
  emits: ['update:selected', 'detail', 'copy', 'move', 'delete', 'download', 'touchstart', 'touchend', 'touchmove'],
  data() {
    return {
      localSelected: this.selected,
      videoLoading: true,
      videoError: false,
      displaySrc: '',
      imgRelease: null,
      imgToken: 0
    };
  },
  computed: {
    channelTag() {
      return this.item.channelTag || '';
    },
    isVideo() {
      // 先通过 content-type 判断
      const fileType = this.item.metadata?.FileType?.toLowerCase() || '';
      if (fileType.includes('video')) return true;
      // 再通过文件后缀判断
      const name = this.item.name?.toLowerCase() || '';
      return name.endsWith('.mp4') || name.endsWith('.webm') || name.endsWith('.mov') || name.endsWith('.avi');
    },
    isAudio() {
      // 先通过 content-type 判断
      const fileType = this.item.metadata?.FileType?.toLowerCase() || '';
      if (fileType.includes('audio')) return true;
      // 再通过文件后缀判断
      const name = this.item.name?.toLowerCase() || '';
      return name.endsWith('.mp3') || name.endsWith('.wav') || name.endsWith('.ogg') || name.endsWith('.flac');
    },
    isImage() {
      // 先通过 content-type 判断
      const fileType = this.item.metadata?.FileType?.toLowerCase() || '';
      if (fileType.includes('image')) return true;
      // 再通过文件后缀判断
      const name = this.item.name?.toLowerCase() || '';
      return name.endsWith('.jpg') || name.endsWith('.jpeg') || name.endsWith('.png') || name.endsWith('.gif') || name.endsWith('.webp') || name.endsWith('.svg') || name.endsWith('.bmp') || name.endsWith('.avif') || name.endsWith('.heic') || name.endsWith('.heif');
    },
    displayName() {
      const fileName = this.item.metadata?.FileName || this.item.name || '';
      const parts = fileName.split('/');
      return parts[parts.length - 1];
    },
    thumbSrc() {
      // 图片预览用缩略图（后端 /file?width= 走 Cloudflare Image Resizing）
      // 统一尺寸：列表与卡片共用同一 width，保证每张图每月只计 1 次唯一转换
      if (!this.isImage) return this.fileLink;
      try {
        const u = new URL(this.fileLink, window.location.origin);
        u.searchParams.set('width', '512');
        return u.toString();
      } catch (e) {
        return this.fileLink;
      }
    }
  },
  watch: {
    selected(val) {
      this.localSelected = val;
    },
    fileLink() {
      // 链接变化时重置加载状态
      this.videoLoading = true;
      this.videoError = false;
    },
    thumbSrc() {
      // 换图时重新排队加载缩略图
      this.queueImage();
    }
  },
  methods: {
    handleVideoError() {
      this.videoLoading = false;
      this.videoError = true;
    },
    handleVideoClick(e) {
      const video = e.target;
      if (video.requestFullscreen) {
        video.requestFullscreen();
      } else if (video.webkitRequestFullscreen) {
        video.webkitRequestFullscreen();
      } else if (video.mozRequestFullScreen) {
        video.mozRequestFullScreen();
      } else if (video.msRequestFullscreen) {
        video.msRequestFullscreen();
      }
    },
    handleFullscreenChange(e) {
      const video = e.target;
      const isFullscreen = document.fullscreenElement || document.webkitFullscreenElement || document.mozFullScreenElement || document.msFullscreenElement;
      if (isFullscreen) {
        // 进入全屏：取消静音和循环
        video.muted = false;
        video.loop = false;
      } else {
        // 退出全屏：恢复静音和循环，暂停并重置
        video.muted = true;
        video.loop = true;
        video.pause();
        video.currentTime = 0;
      }
    },
    handleVideoHover(e, isEnter) {
      const video = e.target;
      if (isEnter) {
        video.play().catch(() => {});
      } else {
        video.pause();
        video.currentTime = 0;
      }
    },
    async queueImage() {
      this.releaseImageSlot();
      this.displaySrc = '';
      const token = ++this.imgToken;
      const release = await acquireImageSlot();
      if (token !== this.imgToken) {
        // 等待期间已换图/销毁，归还槽位
        release();
        return;
      }
      this.imgRelease = release;
      this.displaySrc = this.thumbSrc;
    },
    releaseImageSlot() {
      if (this.imgRelease) {
        this.imgRelease();
        this.imgRelease = null;
      }
    }
  },
  mounted() {
    this.queueImage();
  },
  beforeUnmount() {
    // 销毁时归还槽位，避免队列卡死
    this.releaseImageSlot();
  }
};