    },
    isImage() {
      const name = this.item.name?.toLowerCase() || '';
      return name.endsWith('.jpg') || name.endsWith('.jpeg') || name.endsWith('.png') || name.endsWith('.gif') || name.endsWith('.webp') || name.endsWith('.svg') || name.endsWith('.bmp');
    },
    displayName() {
