/**
 * 缩略图加载队列
 *
 * 限制同一时间正在进行的图片请求数量。列表/卡片一次性并发太多缩略图请求时，
 * 每张缩略图都会让 Cloudflare Image Resizing 回源下载整张原图（Telegram 上的原图
 * 可达十几 MB），并发过高会把源站拖慢并触发 CF 的下载超时（ERROR 9504）。
 *
 * 槽位应在图片 load/error、或组件销毁时释放。这里额外做「幂等释放 + 超时兜底」，
 * 避免任何一处遗漏把队列永久卡死（表现为后续图片连请求都不发）。
 */

const MAX_CONCURRENT = 3;
const SLOT_TIMEOUT_MS = 30000;

let active = 0;
const waiters = [];

function releaseSlot() {
    active = Math.max(0, active - 1);
    const next = waiters.shift();
    if (next) next();
}

function makeRelease() {
    let released = false;
    let timer = null;
    const doRelease = () => {
        if (released) return;
        released = true;
        if (timer) clearTimeout(timer);
        releaseSlot();
    };
    // 兜底：即使调用方从未释放，槽位最多占用 SLOT_TIMEOUT_MS
    timer = setTimeout(doRelease, SLOT_TIMEOUT_MS);
    return doRelease;
}

/**
 * 申请一个图片加载槽位。
 * @returns {Promise<Function>} resolve 出一个幂等的 release 函数（重复调用只释放一次）
 */
export function acquireImageSlot() {
    if (active < MAX_CONCURRENT) {
        active += 1;
        return Promise.resolve(makeRelease());
    }
    return new Promise((resolve) => {
        waiters.push(() => {
            active += 1;
            resolve(makeRelease());
        });
    });
}
